//! ShellResolver and trusted synthetic launchers (DOMAIN_MODEL "Member").
//!
//! Synthetic launchers are generated by the core from fixed, typed fields
//! (a shell found on this machine, a WSL distribution name, an ssh host
//! alias, a tmux session name). They are never built from frontend command
//! text, and they still go through workspace authorization.

use crate::discovery::linux::find_program;
use crate::model::{Descriptor, DescriptorKind, OriginKind, ParseStatus, Platform, RawLauncher};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;

/// User-requested synthetic launchers, persisted by kind + validated fields.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum SyntheticSpec {
    /// `ssh -- <host>` using the user's own ssh config/agent.
    Ssh { host: String },
    /// `ssh -t -- <host> tmux new-session -A -s <session>`.
    SshTmux { host: String, session: String },
    /// Local `tmux new-session -A -s <session>`.
    Tmux { session: String },
}

/// ssh host alias grammar: no leading '-', so it can never become an option.
pub fn valid_host(host: &str) -> bool {
    (1..=253).contains(&host.len())
        && !host.starts_with('-')
        && host
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "._-@:[]".contains(c))
}

pub fn valid_session(name: &str) -> bool {
    (1..=64).contains(&name.len())
        && !name.starts_with('-')
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "_-".contains(c))
}

impl SyntheticSpec {
    pub fn validate(&self) -> Result<(), String> {
        let host_ok = |h: &str| {
            valid_host(h).then_some(()).ok_or_else(|| {
                "host must be an ssh alias or host name (letters, digits, . _ - @ :)".to_string()
            })
        };
        let session_ok = |s: &str| {
            valid_session(s)
                .then_some(())
                .ok_or_else(|| "session name may contain letters, digits, _ and -".to_string())
        };
        match self {
            SyntheticSpec::Ssh { host } => host_ok(host),
            SyntheticSpec::SshTmux { host, session } => host_ok(host).and(session_ok(session)),
            SyntheticSpec::Tmux { session } => session_ok(session),
        }
    }

    pub fn launcher_id(&self) -> String {
        match self {
            SyntheticSpec::Ssh { host } => format!("sys:ssh:{host}"),
            SyntheticSpec::SshTmux { host, session } => format!("sys:ssh-tmux:{host}:{session}"),
            SyntheticSpec::Tmux { session } => format!("sys:tmux:{session}"),
        }
    }
}

fn path_var() -> Option<String> {
    std::env::var("PATH").ok()
}

fn locate(name: &str) -> Option<String> {
    if cfg!(windows) {
        let path = path_var()?;
        std::env::split_paths(&path)
            .map(|d| d.join(format!("{name}.exe")))
            .find(|p| p.is_file())
            .map(|p| p.to_string_lossy().into_owned())
    } else {
        find_program(name, path_var().as_deref()).map(|p| p.to_string_lossy().into_owned())
    }
}

fn synthetic(
    id: String,
    name: String,
    program: Option<String>,
    args: Vec<String>,
    fallback_program: &str,
) -> RawLauncher {
    let available = program.is_some();
    RawLauncher {
        launcher_id: id,
        display_name: name,
        platform: Platform::current(),
        origin: OriginKind::Synthetic,
        origin_root: "toolonize".into(),
        relative_path: String::new(),
        descriptor: Descriptor {
            kind: DescriptorKind::SyntheticSystem,
            program: Some(program.unwrap_or_else(|| fallback_program.to_string())),
            args,
            raw_args: None,
            exec_template: None,
            working_dir: None,
            terminal: true,
            try_exec: None,
            icon: None,
            path_resolved: false,
            source_path: String::new(),
        },
        parse_status: if available {
            ParseStatus::Ok
        } else {
            ParseStatus::Unavailable
        },
        issues: if available {
            vec![]
        } else {
            vec![format!("{fallback_program} was not found on PATH")]
        },
        no_display: false,
        not_shown_here: false,
        comment: None,
    }
}

/// Built-in shells available on this machine (T-PTY-001 surface).
pub fn system_shells() -> Vec<RawLauncher> {
    let mut out = Vec::new();
    if cfg!(windows) {
        let system_root = std::env::var("SystemRoot").unwrap_or_else(|_| "C:\\Windows".into());
        let system32 = PathBuf::from(&system_root).join("System32");
        if let Some(pwsh) = locate("pwsh") {
            out.push(synthetic(
                "sys:shell:pwsh".into(),
                "PowerShell 7".into(),
                Some(pwsh),
                vec!["-NoLogo".into()],
                "pwsh",
            ));
        }
        let powershell = system32.join("WindowsPowerShell\\v1.0\\powershell.exe");
        out.push(synthetic(
            "sys:shell:powershell".into(),
            "Windows PowerShell".into(),
            powershell
                .is_file()
                .then(|| powershell.to_string_lossy().into_owned()),
            vec!["-NoLogo".into()],
            "powershell.exe",
        ));
        let cmd = system32.join("cmd.exe");
        out.push(synthetic(
            "sys:shell:cmd".into(),
            "Command Prompt".into(),
            cmd.is_file().then(|| cmd.to_string_lossy().into_owned()),
            vec![],
            "cmd.exe",
        ));
        let wsl = system32.join("wsl.exe");
        if wsl.is_file() {
            let wsl_path = wsl.to_string_lossy().into_owned();
            for distro in wsl_distributions() {
                out.push(synthetic(
                    format!("sys:wsl:{distro}"),
                    format!("WSL: {distro}"),
                    Some(wsl_path.clone()),
                    vec!["-d".into(), distro.clone()],
                    "wsl.exe",
                ));
            }
        }
    } else {
        let mut seen = Vec::new();
        let login = std::env::var("SHELL").ok().filter(|s| s.starts_with('/'));
        if let Some(shell) = login.as_deref().and_then(|s| find_program(s, None)) {
            let name = shell
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_else(|| "shell".into());
            seen.push(name.clone());
            out.push(synthetic(
                format!("sys:shell:{name}"),
                format!("{name} (login shell)"),
                Some(shell.to_string_lossy().into_owned()),
                vec!["-l".into()],
                &name,
            ));
        }
        for name in ["bash", "zsh", "fish", "sh"] {
            if seen.iter().any(|s| s == name) {
                continue;
            }
            if let Some(path) = locate(name) {
                out.push(synthetic(
                    format!("sys:shell:{name}"),
                    name.to_string(),
                    Some(path),
                    vec![],
                    name,
                ));
            }
        }
    }
    out
}

pub fn synthetic_launcher(spec: &SyntheticSpec) -> RawLauncher {
    let ssh = || locate("ssh");
    match spec {
        SyntheticSpec::Ssh { host } => synthetic(
            spec.launcher_id(),
            format!("ssh {host}"),
            ssh(),
            vec!["--".into(), host.clone()],
            "ssh",
        ),
        SyntheticSpec::SshTmux { host, session } => synthetic(
            spec.launcher_id(),
            format!("ssh {host} · tmux {session}"),
            ssh(),
            vec![
                "-t".into(),
                "--".into(),
                host.clone(),
                "tmux".into(),
                "new-session".into(),
                "-A".into(),
                "-s".into(),
                session.clone(),
            ],
            "ssh",
        ),
        SyntheticSpec::Tmux { session } => synthetic(
            spec.launcher_id(),
            format!("tmux {session}"),
            locate("tmux"),
            vec![
                "new-session".into(),
                "-A".into(),
                "-s".into(),
                session.clone(),
            ],
            "tmux",
        ),
    }
}

/// Registered WSL distributions from the per-user Lxss registry key (read
/// only; nothing is executed to enumerate them).
#[cfg(windows)]
pub fn wsl_distributions() -> Vec<String> {
    use windows_sys::Win32::System::Registry::{
        RegCloseKey, RegEnumKeyExW, RegGetValueW, RegOpenKeyExW, HKEY, HKEY_CURRENT_USER, KEY_READ,
        RRF_RT_REG_SZ,
    };
    fn wide(s: &str) -> Vec<u16> {
        s.encode_utf16().chain(std::iter::once(0)).collect()
    }
    let mut names = Vec::new();
    // SAFETY: standard registry enumeration with buffers sized per call;
    // the key handle is closed before returning.
    unsafe {
        let mut key: HKEY = std::ptr::null_mut();
        let path = wide("Software\\Microsoft\\Windows\\CurrentVersion\\Lxss");
        if RegOpenKeyExW(HKEY_CURRENT_USER, path.as_ptr(), 0, KEY_READ, &mut key) != 0 {
            return names;
        }
        for index in 0..64u32 {
            let mut buf = [0u16; 256];
            let mut len = buf.len() as u32;
            let rc = RegEnumKeyExW(
                key,
                index,
                buf.as_mut_ptr(),
                &mut len,
                std::ptr::null(),
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                std::ptr::null_mut(),
            );
            if rc != 0 {
                break;
            }
            let value = wide("DistributionName");
            let mut data = [0u16; 256];
            let mut size = (data.len() * 2) as u32;
            let rc = RegGetValueW(
                key,
                buf.as_ptr(),
                value.as_ptr(),
                RRF_RT_REG_SZ,
                std::ptr::null_mut(),
                data.as_mut_ptr() as _,
                &mut size,
            );
            if rc == 0 {
                let chars = (size as usize / 2).saturating_sub(1);
                let name = String::from_utf16_lossy(&data[..chars.min(data.len())]);
                if valid_session(&name.replace('.', "-")) {
                    names.push(name);
                }
            }
        }
        RegCloseKey(key);
    }
    names
}

#[cfg(not(windows))]
pub fn wsl_distributions() -> Vec<String> {
    Vec::new()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn host_and_session_grammar_blocks_option_injection() {
        assert!(valid_host("build-server.example.com"));
        assert!(valid_host("alice@build.example.com"));
        assert!(!valid_host("-oProxyCommand=evil"));
        assert!(!valid_host("host; rm -rf ~"));
        assert!(!valid_host("host name"));
        assert!(!valid_host(""));
        assert!(valid_session("main"));
        assert!(!valid_session("-x"));
        assert!(!valid_session("a;b"));
    }

    #[test]
    fn ssh_spec_builds_fixed_argv() {
        let spec = SyntheticSpec::SshTmux {
            host: "build.example.com".into(),
            session: "main".into(),
        };
        assert!(spec.validate().is_ok());
        let raw = synthetic_launcher(&spec);
        assert_eq!(raw.launcher_id, "sys:ssh-tmux:build.example.com:main");
        assert_eq!(raw.descriptor.args[..3], ["-t", "--", "build.example.com"]);
        assert_eq!(raw.origin, OriginKind::Synthetic);
        assert!(SyntheticSpec::Ssh {
            host: "-oProxyCommand=x".into()
        }
        .validate()
        .is_err());
    }

    #[cfg(unix)]
    #[test]
    fn finds_at_least_sh() {
        let shells = system_shells();
        assert!(shells
            .iter()
            .any(|s| s.launcher_id.starts_with("sys:shell:")));
        assert!(shells
            .iter()
            .all(|s| s.descriptor.kind == DescriptorKind::SyntheticSystem));
    }
}
